<?php
namespace App\Services; use App\Config\Database;
final class RefundService { public function refund(int $orderId,string $reason='rejected'):void{$db=Database::get();$db->beginTransaction();try{$q=$db->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$q->execute([$orderId]);$o=$q->fetch();if(!$o)throw new \RuntimeException('Order tidak ditemukan');if($o['refund_status']==='refunded'){$db->commit();return;}WalletService::move($db,(int)$o['user_id'],(float)$o['selling_price'],'refund',(string)$o['order_number'],'refund:'.$o['id']);$db->prepare("UPDATE orders SET refund_status='refunded',status='refunded',reject_reason=?,completed_at=NOW() WHERE id=?")->execute([$reason,$orderId]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}}
